import{_ as d,o as r,c as a,ag as e}from"./chunks/framework.CtWPcAmt.js";const A=JSON.parse('{"title":"附录 A：核心术语表","description":"全书术语按字母/主题排序的白话解释，首次出现术语的集中查询处。","frontmatter":{"title":"附录 A：核心术语表","description":"全书术语按字母/主题排序的白话解释，首次出现术语的集中查询处。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"appendix/00-glossary.md","filePath":"appendix/00-glossary.md","lastUpdated":null}'),h={name:"appendix/00-glossary.md"};function o(n,t,i,l,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="附录-a-核心术语表" tabindex="-1">附录 A：核心术语表 <a class="header-anchor" href="#附录-a-核心术语表" aria-label="Permalink to &quot;附录 A：核心术语表&quot;">​</a></h1><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><p>每个术语先给一句话白话解释，再给正式说明与出处章节。术语在正文首次出现时都有一句白话，这里是把它们集中起来，方便你随时回来查。</p><h2 id="a-基本概念" tabindex="-1">A. 基本概念 <a class="header-anchor" href="#a-基本概念" aria-label="Permalink to &quot;A. 基本概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>正式说明</th><th>出处</th></tr></thead><tbody><tr><td>AI Agent（智能体）</td><td>一个「会自己干活」的 AI，而不是只会回答</td><td>能接收目标、规划步骤、调用工具并交付结果的 AI 程序</td><td>第 1 章</td></tr><tr><td>模型（Model）</td><td>Agent 的「大脑」</td><td>通过大规模训练学会理解与生成自然语言等内容的神经网络</td><td>第 1 章</td></tr><tr><td>上下文（Context）</td><td>Agent 眼前摊开的全部信息</td><td>本次任务中它能看到的输入总和：你的话、文件、规则</td><td>第 1、11 章</td></tr><tr><td>上下文窗口</td><td>一次能摊在桌面上的材料上限</td><td>模型单次可处理的输入总量</td><td>第 11 章</td></tr><tr><td>工具（Tool）</td><td>Agent 能用的「手脚」</td><td>可调用的外部能力：读文件、写文件、运行、联网</td><td>第 1 章</td></tr><tr><td>记忆（Memory）</td><td>Agent 的「长期笔记本」</td><td>跨任务保存的偏好、约定、历史要点</td><td>第 1、14 章</td></tr><tr><td>权限（Permission）</td><td>Agent 的「门禁卡」</td><td>对行为范围的限制：能读什么、写什么、能否联网</td><td>第 1、8 章</td></tr><tr><td>聊天 AI</td><td>只「回答」的 AI</td><td>生成回答但不主动执行任务的形态</td><td>第 1 章</td></tr><tr><td>Copilot（副驾驶）</td><td>在你操作时给建议的 AI</td><td>编辑器等场景中补全、建议但不独立执行完整任务</td><td>第 1 章</td></tr></tbody></table><h2 id="b-能力与风险" tabindex="-1">B. 能力与风险 <a class="header-anchor" href="#b-能力与风险" aria-label="Permalink to &quot;B. 能力与风险&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>正式说明</th><th>出处</th></tr></thead><tbody><tr><td>幻觉（Hallucination）</td><td>一本正经地胡说八道</td><td>生成看似合理但实际错误的内容</td><td>第 2 章</td></tr><tr><td>遗漏（Omission）</td><td>6 道题只做了 4 道</td><td>任务部分完成且可能不告知</td><td>第 2 章</td></tr><tr><td>误操作（Misoperation）</td><td>改错、删错</td><td>执行时改动/删除了不该动的内容</td><td>第 2 章</td></tr><tr><td>越权（Overreach）</td><td>碰了不该碰的</td><td>行为超出授予的范围</td><td>第 2、8 章</td></tr><tr><td>自检（Self-check）</td><td>Agent 交卷前的自我检查</td><td>产品内置的交付前检查；<strong>不等于可信保证</strong></td><td>第 2、10 章</td></tr><tr><td>事实核查（Fact check）</td><td>核对数字和来源</td><td>验证输出中的事实、数字、来源是否真实</td><td>第 10 章</td></tr><tr><td>文件检查（File check）</td><td>数一数交了几份</td><td>核对交付物数量、名称、格式、位置</td><td>第 10 章</td></tr></tbody></table><h2 id="c-任务与协作" tabindex="-1">C. 任务与协作 <a class="header-anchor" href="#c-任务与协作" aria-label="Permalink to &quot;C. 任务与协作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>正式说明</th><th>出处</th></tr></thead><tbody><tr><td>任务卡（Task Brief）</td><td>给 Agent 的施工单</td><td>六要素结构化的任务描述：目标/上下文/材料/约束/交付物/验收标准</td><td>第 7 章</td></tr><tr><td>验收标准</td><td>完工检查单</td><td>可逐项打勾的完成条件</td><td>第 7、10 章</td></tr><tr><td>约束（Constraints）</td><td>允许什么、禁止什么</td><td>范围、权限、格式等限制</td><td>第 7 章</td></tr><tr><td>委派等级（L1–L4）</td><td>任务交给它的放心程度</td><td>全自动/分段确认/人工关键步/不委派</td><td>第 2 章</td></tr><tr><td>分段确认（Checkpoint）</td><td>每段验收再继续</td><td>关键节点暂停由人确认</td><td>第 9 章</td></tr><tr><td>偏航（Drift）</td><td>跑偏了</td><td>执行偏离目标或约束</td><td>第 9 章</td></tr><tr><td>接管（Takeover）</td><td>人直接介入纠正</td><td>及时纠正 Agent 当前动作</td><td>第 9 章</td></tr><tr><td>复盘（Retrospective）</td><td>打完仗开总结会</td><td>任务后回顾并沉淀经验</td><td>第 10 章</td></tr></tbody></table><h2 id="d-选型与计费" tabindex="-1">D. 选型与计费 <a class="header-anchor" href="#d-选型与计费" aria-label="Permalink to &quot;D. 选型与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>正式说明</th><th>出处</th></tr></thead><tbody><tr><td>托管路径</td><td>买产品套餐直接用</td><td>产品官方订阅提供的托管能力</td><td>第 6 章</td></tr><tr><td>BYOK（自带密钥）</td><td>自己租模型算力插进去</td><td>在 Agent 里填 API Key，供应商直接计费</td><td>第 4、6 章</td></tr><tr><td>Credits / 积分 / Token</td><td>各产品的用量单位</td><td>计量单位互不相同，<strong>不按数值横比</strong></td><td>第 4、6 章</td></tr><tr><td>需求卡</td><td>你的选型需求清单</td><td>任务/地区/预算/边界/偏好八问</td><td>第 4 章</td></tr><tr><td>四组分类</td><td>建立直觉的分组</td><td>海外综合/国内综合/代码优先/开源自主</td><td>第 4 章</td></tr><tr><td>六维评分</td><td>分维度比较的尺子</td><td>交付/预览/变更/过程/边界/恢复</td><td>第 6 章</td></tr></tbody></table><h2 id="e-进阶与系统" tabindex="-1">E. 进阶与系统 <a class="header-anchor" href="#e-进阶与系统" aria-label="Permalink to &quot;E. 进阶与系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>正式说明</th><th>出处</th></tr></thead><tbody><tr><td>模板（Template）</td><td>填空题试卷</td><td>固定结构 + 变量占位，可复用文档</td><td>第 12 章</td></tr><tr><td>Skill（技能）</td><td>给 Agent 装的能力插件</td><td>指令+参考资料+脚本+资源打包的可调用能力单元</td><td>第 13 章</td></tr><tr><td>Slash 命令</td><td>用 /技能名 快速调用</td><td>产品内调用 Skill 的快捷方式</td><td>第 13 章</td></tr><tr><td>全局规则 / 项目规则</td><td>管所有任务 / 管一个项目</td><td>规则的两级组织</td><td>第 14 章</td></tr><tr><td>记忆淘汰（Eviction）</td><td>清理笔记本旧页</td><td>删除过时/错误的记忆</td><td>第 14 章</td></tr><tr><td>Harness</td><td>给 AI 配的工作台+规矩</td><td>围绕模型搭建的工作系统：Agent/上下文/工具/权限/状态/验证/反馈</td><td>第 15 章</td></tr><tr><td>六层架构</td><td>系统的六个部门</td><td>入口/上下文/执行/安全/验证/反馈</td><td>第 16 章</td></tr><tr><td>多 Agent 协作</td><td>分工而不是人数优势</td><td>并行/串行/评审/仲裁四种模式</td><td>第 17 章</td></tr><tr><td>交付协议（Handoff）</td><td>交接班记录表</td><td>Agent 间传递产物的格式与规则</td><td>第 17 章</td></tr><tr><td>一次通过率</td><td>不返工的占比</td><td>任务健康核心指标</td><td>第 18 章</td></tr><tr><td>回归验证</td><td>修完门检查其他门</td><td>修改后重跑历史任务确认没改坏</td><td>第 18 章</td></tr><tr><td>可恢复设计</td><td>每一步都有后悔药</td><td>备份、版本、独立输出目录</td><td>第 8、18 章</td></tr></tbody></table>',13)])])}const p=d(h,[["render",o]]);export{A as __pageData,p as default};
